#ifdef VIBERA_TUNE_RESOURCE_AUDIT
extern "C" void vibera_tune_resource_event(int, std::size_t) noexcept;
#endif

namespace RubberBand {

T *allocate(size_t count)
{
#ifdef VIBERA_TUNE_RESOURCE_AUDIT
    vibera_tune_resource_event(1, count * sizeof(T));
#endif
    void *ptr = 0;

void deallocate(T *ptr)
{
    if (!ptr) return;
#ifdef VIBERA_TUNE_RESOURCE_AUDIT
    vibera_tune_resource_event(2, 0);
#endif
